INSERT INTO `employees` VALUES (1, '雅南', '林', '林雅南', '26', '女', 4, '女士', '1988-12-08 00:00:00', '2012-05-01 00:00:00', '复兴门 245 号', '北京', '华北', '100098', '中国', '13722983899', '5467', , '获北京大学心理学学士学位。她同时完成了“冷食的艺术”。林雅南是国际美食协会的会员。', 2, 2, 1, 'zy@northwind.com', 'http://www.smartbi.com.cn', 2000);
INSERT INTO `employees` VALUES (2, '奕云', '江', '江奕云', '41', '男', 2, '博士', '1982-02-19 00:00:00', '2012-08-14 00:00:00', '罗马花园 890 号', '北京', '华北', '109801', '中国', '18376920879', '3457', , '江奕云获南京大学商业学士学位，获该校国际营销博士学位。他能说流利的法语和意大利语并能阅读德语。他加入公司时是销售代表，被提拔为销售经理并升任销售副总裁。江奕云是销售管理圆桌协会，北京商业总会和太平洋周边进口协会的成员。', 5, 1, 3, 'ww@northwind.com', 'http://www.smartbi.com.cn', 2000);
INSERT INTO `employees` VALUES (3, '美丽', '夏', '夏美丽', '23', '女', 4, '女士', '1991-02-28 00:00:00', '2012-04-01 00:00:00', '芍药园小区 78 号', '北京', '华北', '198033', '中国', '13689370497', '3355', , '夏美丽获北京学院化学学士学位。她同时完成了食品零售管理资格程序。夏美丽被雇用为销售员并提升为销售代表。', 2, 2, 1, 'lf@northwind.com', 'http://www.smartbi.com.cn', 2000);
INSERT INTO `employees` VALUES (4, '国瑞', '林', '林国瑞', '26', '男', 4, '先生', '1988-09-19 00:00:00', '2013-05-03 00:00:00', '前门大街 789 号', '北京', '华北', '198052', '中国', '18837420094', '5176', , '林国瑞持有外国语学院英国文学学士学位和中国烹调艺术学院硕士学位。在他返回到北京的永久职位之前被临时派往上海办公室工作。', 2, 1, 2, 'zjj@northwind.com', 'http://www.smartbi.com.cn', 2000);
INSERT INTO `employees` VALUES (5, '柏宏', '刘', '刘柏宏', '38', '男', 3, '先生', '1985-03-04 00:00:00', '2011-10-17 00:00:00', '学院路 78 号', '北京', '华北', '100090', '中国', '13987888902', '3453', , '刘柏宏毕业于复旦大学，获学士学位。自从加入公司成为一名销售代表，他花了6个月时间在北京办公室进行适应性工作，然后回到他在上海的固定职位。他被提拔为销售经理。刘柏宏先生完成了课程“成功的电话销售”和“国际销售管理”。他的法语非常流利。', 2, 1, 1, 'zj@northwind.com', 'http://www.smartbi.com.cn', 2000);
INSERT INTO `employees` VALUES (6, '吉惟', '张', '张吉惟', '31', '男', 4, '先生', '1983-11-24 00:00:00', '2012-10-17 00:00:00', '阜外大街 110 号', '北京', '华北', '100678', '中国', '13387332099', '428', , '张吉惟是交通大学（经济学硕士）和北京的清华大学的研究生（工商管理硕士）。他同时完成了课程“多元文化销售”和“销售专业人员时间管理”。他日语流利并能读写法语、葡萄牙语和西班牙语。', 5, 1, 2, 'sl@northwind.com', 'http://www.smartbi.com.cn', 2000);
INSERT INTO `employees` VALUES (7, '子帆', '林', '林子帆', '43', '男', 4, '先生', '1980-05-29 00:00:00', '2010-01-02 00:00:00', '成府路 119 号', '北京', '华北', '100345', '中国', '13590922345', '465', , '林子帆在完成他在交通大学的英语学位之前服务于和平公司并旅行了很多地方。此后他加入本公司。完成“在华北销售”的课程之后，他被调到上海办公室。', 5, 1, 1, 'jsp@northwind.com', 'http://www.smartbi.com.cn', 2000);
INSERT INTO `employees` VALUES (8, '玟书', '林', '林玟书', '44', '女', 5, '女士', '1979-01-09 00:00:00', '2010-03-05 00:00:00', '建国门 76 号', '北京', '华北', '198105', '中国', '13722368790', '2344', , '林玟书获得北京大学心理学学士学位。她同时完成了一门商务法语课程。她能读写法语。', 2, 2, 1, 'lym@northwind.com', 'http://www.smartbi.com.cn', 2000);
INSERT INTO `employees` VALUES (9, '雪眉', '张', '张雪眉', '30', '女', 4, '女士', '1984-08-23 00:00:00', '2010-11-15 00:00:00', '永安路 678 号', '北京', '华北', '100056', '中国', '13428749309', '452', , '张雪眉获得科技大学英语学士学位。她的法语和德语都很流利。', 5, 2, 1, 'zxm@northwind.com', 'http://www.smartbi.com.cn', 2000);
